import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadAncientPortsScript(){const e=readFileSync(resolve(__dirname,"../../ancient-ports-explorer/script.js"),"utf-8");return new Function("window","document",e+"\nreturn window.AncientPorts;")({},{readyState:"complete",addEventListener:()=>{},getElementById:()=>null,querySelectorAll:()=>[]})}describe("Ancient Ports of India Explorer Landing Page Tests",()=>{let e;beforeAll(()=>{e=loadAncientPortsScript()}),it("loads Ancient Ports dataset properly",()=>{expect(e).toBeDefined(),expect(Array.isArray(e.ANCIENT_PORTS)).toBe(!0),expect(e.ANCIENT_PORTS.length).toBeGreaterThanOrEqual(12)}),it("contains Lothal, Muziris, Arikamedu, and Tamralipta in dataset",()=>{const t=e.ANCIENT_PORTS.map(e=>e.id);expect(t).toContain("lothal"),expect(t).toContain("muziris"),expect(t).toContain("arikamedu"),expect(t).toContain("tamralipta")}),it("all ports have required metadata fields",()=>{e.ANCIENT_PORTS.forEach(e=>{expect(e.id).toBeDefined(),expect(e.name).toBeDefined(),expect(e.state).toBeDefined(),expect(e.dynasty).toBeDefined(),expect(e.timePeriod).toBeDefined(),expect(e.coast).toBeDefined(),expect(e.url).toBeDefined()})}),it("HTML structure has required section IDs and accessibility attributes",()=>{const e=readFileSync(resolve(__dirname,"../../ancient-ports-explorer/index.html"),"utf-8");expect(e).toContain('id="ports-explorer"'),expect(e).toContain('id="interactive-map"'),expect(e).toContain('id="timeline"'),expect(e).toContain('id="stats"'),expect(e).toContain('id="education"'),expect(e).toContain('id="port-search-input"'),expect(e).toContain('id="filter-state"'),expect(e).toContain('id="filter-dynasty"'),expect(e).toContain('id="filter-time"'),expect(e).toContain('id="filter-coast"'),expect(e).toContain('id="filter-unesco"')})});